function count_open(s: string): int
    requires s != null
    ensures count_open(s) >= 0
    ensures count_open(s) == |{i | i in 0 .. s.Length && s[i] == '('}|
{
    var count := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == |{j | j in 0 .. i && s[j] == '('}|
    {
        if s[i] == '(' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function count_close(s: string): int
    requires s != null
    ensures count_close(s) >= 0
    ensures count_close(s) == |{i | i in 0 .. s.Length && s[i] == ')'}|
{
