    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant count == |{j | j in 0 .. i && s[j] == ')'}|
    {
        if s[i] == ')' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function IsBalanced(s: string): bool
    requires s != null
    ensures IsBalanced(s) ==> count_open(s) == count_close(s)
{
    return count_open(s) == count_close(s);
